"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2020],{2685(e){e.exports=JSON.parse('{"title":"JavaScript\uc640 SEO\uc5d0 \ub300\ud55c \uc9c4\uc2e4\uacfc \uac70\uc9d3","date":"2024-08-07","coverUrl":null,"html":"<h2 data-notion-block-id=\\"53ed0e90-c49d-47b4-9506-fd018c416b77\\" id=\\"53ed0e90-c49d-47b4-9506-fd018c416b77\\">JavaScript\uc640 SEO\uc5d0 \ub300\ud55c \uc9c4\uc2e4\uacfc \uac70\uc9d3</h2><a href=\\"https://vercel.com/blog/how-google-handles-javascript-throughout-the-indexing-process\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/how-google-handles-javascript-throughout-the-indexing-process</a><p data-notion-block-id=\\"3ead13dd-1b01-4620-8737-9c073dfc2722\\"><b>\uc2ec\uc724\uc12d</b>: SEO\uc5d0 \ub300\ud55c \uc798\ubabb\ub41c \uc18d\uc124\uc744 \ubc14\ub85c\uc7a1\ub294 \uae00\uc785\ub2c8\ub2e4. \uad6c\uae00\uc740 SPA\uc640 SSR \uad6c\ubd84 \uc5c6\uc774 \ubaa8\ub4e0 \ucee8\ud150\uce20\ub97c \ub85c\ub529 \ubc0f \ub80c\ub354\ub9c1\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub80c\ub354\ub9c1 \uc131\ub2a5\uc744 \ud1b5\ud574 \ud06c\ub864\ub9c1 \ud6a8\uc728 \uac1c\uc120, \ucee8\ud150\uce20 \uac00\uce58 \ud5a5\uc0c1\uc744 \ud1b5\ud574 \uc6b0\uc120\uc21c\uc704\ub97c \ub192\uc774\ub294 \uacfc\uc815\uc744 \ub192\uc774\ub77c\ub294 \uc810\uc744 \uac15\uc870\ud569\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 SEO\uc5d0 \uc601\ud5a5\uc744 \ub07c\uce58\ub294 \uc694\uc18c\uac00 \uc5ec\ub7ec\uac1c \uc788\uc73c\ub2c8 \ub354 \uc790\uc138\ud788 \uc54c\uc544\ubcf4\uc2e4 \ubd84\uc740 <a href=\\"https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=ko\\">SEO \uae30\ubcf8 \uac00\uc774\ub4dc</a>\ub97c \ubcf4\uc138\uc694.</p><p data-notion-block-id=\\"0ec80f9f-4cae-4004-bfa6-def97f4bbae9\\"><b>\uae40\ub300\uad00</b>: \uad6c\uae00\uc5d0\uc11c\uc758 SPA\uc640 SSR\uc5d0 \ub300\ud55c SEO\uc758 \uc601\ud5a5\uc5d0 \ub300\ud55c \uc774\uc57c\uae30\ub97c \ub098\ub208\ub2e4\uba74 \uaf2d \ub098\ub220\ubcf4\uace0 \uc2f6\uc740 \uc815\ubcf4\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uad6d\ub0b4\uc2dc\uc7a5\ub3c4 \ubc14\ub77c\ubcf4\ub294 \uc11c\ube44\uc2a4\ub77c\uba74 <a href=\\"https://searchadvisor.naver.com/guide/seo-advanced-javascript\\">\ub124\uc774\ubc84 \uc11c\uce58\uc5b4\ub4dc\ubc14\uc774\uc800</a>\uc5d0\uc11c \uad8c\uc7a5\ud558\ub294 SPA\uc5d0\uc11c\uc758 SEO \ud5a5\uc0c1\uc744 \uc704\ud574 \uc77c\ubd80 SSR\uc758 \uae30\ub2a5\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc788\uc73c\ub2c8 \ub193\uce58\uc9c0 \uc54a\uae38 \ubc14\ub78d\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"eb0a607b-732a-4dd2-9ecf-6203c9588a87\\" id=\\"eb0a607b-732a-4dd2-9ecf-6203c9588a87\\">\uc704\uce58\ub294 \uc720\uc800\uc758 \uac70\uc9d3\ub9d0</h2><a href=\\"https://austingil.com/user-location-is-a-lie/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://austingil.com/user-location-is-a-lie/</a><p data-notion-block-id=\\"83f2e04c-5425-4f60-bf39-83c4dd0fdcfe\\"><b>\uc2ec\uc724\uc12d</b>: \uc11c\ube44\uc2a4\ub97c \ub9cc\ub4e4 \ub54c, \ub9ce\uc740 \uacbd\uc6b0\uc5d0 \uc704\uce58\ub97c \ud544\uc694\ub85c \ud569\ub2c8\ub2e4. \uc5b8\uc5b4 \uc124\uc815, \uad6d\uac00 \ud310\ubcc4, \ud574\ub2f9 \uc704\uce58\uc5d0 \ub300\ud55c \ub370\uc774\ud130 \uc81c\uacf5\u2026 \uc774 \uae00\uc740 \uc704\uce58\ub97c \uac00\uc838\uc624\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\uace0, (\ud074\ub77c\uc774\uc5b8\ud2b8\ub97c \uc2e0\ub8b0\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c) \uc5b4\ub290 \uac83\ub3c4 \uc2e0\ub8b0\ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc744 \uc54c\ub9ac\uace0\uc790 \ud569\ub2c8\ub2e4. \uc0ac\uc6a9\uc790\uc758 \ub370\uc774\ud130\ub97c \uc6d0\ud560 \ub54c, \ub370\uc774\ud130\uc758 \uc911\uc694\ub3c4\uc5d0 \ub530\ub77c \uad6c\ud604\ud558\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc8fc\ub294 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4. \uac1c\uc778\uc815\ubcf4\ub294 \uc911\uc694\ud558\ub2c8, \ub9ce\uc740 \uc11c\ube44\uc2a4\uc5d0\uc11c \ud544\uc694\ud55c \ub370\uc774\ud130\ub9cc \uac00\uc838\uac00\ub3c4\ub85d \uad6c\ud604\ud558\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"43aab6b1-8719-470d-aa01-7c87e37f9465\\" id=\\"43aab6b1-8719-470d-aa01-7c87e37f9465\\">CSS \uac12\uc740 \uc5b4\ub5bb\uac8c \uacc4\uc0b0\ub418\ub294\uac00</h2><a href=\\"https://moderncss.dev/how-custom-property-values-are-computed/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://moderncss.dev/how-custom-property-values-are-computed/</a><p data-notion-block-id=\\"920d89e9-775b-4202-8fbf-686cc392f194\\"><b>\uc2ec\uc724\uc12d</b>: \uc0ac\uc6a9\uc790 \uc9c0\uc815 CSS \ubcc0\uc218\ub97c \uc0ac\uc6a9\ud560 \uacbd\uc6b0 \uc885\uc885 CSS \uac12\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\ub358\uac00, \uc0c1\uc18d\uc774 \uc6d0\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \uc885\uc885 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub294 CSS\uc758 \uba85\uc138\uc5d0 \ub530\ub77c \uac12\uc774 \uacc4\uc0b0\ub418\uae30\uc5d0 \uadf8\ub807\uc2b5\ub2c8\ub2e4. CSS \uac12\uc744 \uacc4\uc0b0\ud558\ub294 \ubc29\uc2dd\uc778 CVT\uc640 \uc0c1\uc18d\uc5d0 \ub300\ud55c \uc798\ubabb\ub41c \uc0dd\uac01, \ubaa8\ub358 CSS\uc778 <code>@property</code>\uc5d0 \ub300\ud574 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubaa8\ub358 CSS\uc758 CSS \ubcc0\uc218\ub97c \ud65c\uc6a9\ud558\uc5ec \uc2a4\ud0c0\uc77c\uc744 \uc885\uc18d\ub418\uc9c0 \uc54a\uac8c \ub9cc\ub4e4\uae30\ub3c4 \ud558\ub294\ub370, \uc774 \ub54c \uc911\uc694\ud55c </p><h2 data-notion-block-id=\\"69d68b87-cc5d-4e39-aac2-605b097e716c\\" id=\\"69d68b87-cc5d-4e39-aac2-605b097e716c\\">TypeScript\ub97c \ud574\uc11d\ud558\ub294 \ub2e4\ub978 \uc2dc\uac01</h2><a href=\\"https://www.rob.directory/blog/a-different-way-to-think-about-typescript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.rob.directory/blog/a-different-way-to-think-about-typescript</a><p data-notion-block-id=\\"69748a50-8ace-46d7-bfbc-6993bbb99afa\\">TypeScript\uc758 Intersection, Union, \uc720\ud615 \uac80\uc0ac, mapped type, <code>infer</code> \ud0a4\uc6cc\ub4dc\ub97c \uc0c8\ub85c\uc6b4 \uad00\uc810(\uc9d1\ud569)\uc73c\ub85c \ud574\uc11d\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. TypeScript\ub97c \uacf5\ubd80\ud560 \ub54c \uc5b4\ub824\uc6cc \ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc774 <code>extends</code>, <code>infer</code>, \uadf8\ub9ac\uace0 \uc870\uac74\ubd80 \ud0c0\uc785\uc744 \uacf5\ubd80\ud560 \ub54c \uc5b4\ub824\uc6c0\uc744 \uacaa\uc744 \uc218 \uc788\ub294\ub370, \ub300\ubd80\ubd84\uc758 \uacbd\uc6b0\uc758 \ub17c\ub9ac\ub97c \uc27d\uac8c \uc0dd\uac01\ud558\ub3c4\ub85d \ub3d5\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ubd84\uc0b0 \uc870\uac74\ubd80 \ud0c0\uc785(<a href=\\"https://www.typescriptlang.org/ko/docs/handbook/2/conditional-types.html#\ubd84\uc0b0\uc801\uc778-\uc870\uac74\ubd80-\ud0c0\uc785\\">Distributive Conditional Types</a>)\uc758 \uacbd\uc6b0\ub97c \ub4e4\uba74\uc11c \ud56d\uc0c1 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2c8 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"66f16eb8-0c22-4281-8d90-a9c2e687f435\\" id=\\"66f16eb8-0c22-4281-8d90-a9c2e687f435\\">Barrel File\uc744 \uc4f0\uc9c0 \ub9c8\uc138\uc694.</h2><a href=\\"https://tkdodo.eu/blog/please-stop-using-barrel-files\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/please-stop-using-barrel-files</a><p data-notion-block-id=\\"49cffac1-aec3-4c0b-9aab-e18858779193\\">\uc21c\ud658 import\uc640 import \uc18d\ub3c4 \uac10\uc18c\uc5d0 \uc601\ud5a5\uc744 \ub07c\uce58\ub2c8 \uc0ac\uc6a9\ud558\uc9c0 \ub9d0\uc790\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/dadb3439-b509-4f21-b8a3-4646fdd233af\\">Polyfill\uc740 \ud544\uc694\ud560\ub54c\ub9cc</a>\uc758 \uc800\uc790\ub3c4 \ube44\uc2b7\ud55c \uc8fc\uc81c\ub85c \ube14\ub85c\uadf8 \uae00(<a href=\\"https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-7/\\">barrel file\uc758 \uc2e4\ud328</a>)\uc744 \uc37c\ub124\uc694. \ud504\ub808\uc784\uc6cc\ud06c \uce21\uc5d0\uc11c \uad8c\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc548 \uc4f0\ub294 \uac83\uc774 \ub9de\uaca0\uc8e0!</p><h2 data-notion-block-id=\\"a57c54da-e9fa-4bd8-b9db-c4e1267a3c41\\" id=\\"a57c54da-e9fa-4bd8-b9db-c4e1267a3c41\\"><code>letter-spacing</code>\uc740 \uc815\uc0c1\uc801\uc73c\ub85c \uc791\ub3d9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://css-tricks.com/letter-spacing-is-broken-and-theres-nothing-we-can-do-about-it-maybe/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/letter-spacing-is-broken-and-theres-nothing-we-can-do-about-it-maybe/</a><p data-notion-block-id=\\"4a48de3b-bdf1-437d-ba16-101d688eab09\\"><code>letter-spacing</code>\uc774 \uae00\uc790\uc640 \uae00\uc790 \uc0ac\uc774\uc5d0\ub9cc \uc801\uc6a9\ub418\uc9c0 \uc54a\uace0, \ubb38\uc790\uc758 \ub05d\uc5d0 \ubaa8\ub450 \uc801\uc6a9\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"dfd63e57-a312-482d-b5f8-959ae73c3d1c\\" id=\\"dfd63e57-a312-482d-b5f8-959ae73c3d1c\\">\ud074\ub85c\uc800\uc640 GC\ubb38\uc81c</h2><a href=\\"https://jakearchibald.com/2024/garbage-collection-and-closures/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2024/garbage-collection-and-closures/</a><p data-notion-block-id=\\"d76ab67f-38d8-4ec9-8736-a3c17298b9f9\\">\ud074\ub85c\uc800\ub85c \uc778\ud55c \ud568\uc218 \ubc16\uc758 \ubcc0\uc218\ub97c \ucc38\uc870\ud560 \ub54c \uc870\uc2ec\ud558\ub77c\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\ub294 JS\uc5d0 \ucd08\uc810\uc774 \ub9de\ucdb0\uc84c\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#969cfc7b-5f89-42de-896d-eacff8b32799\\">React\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/5ca5c5cc-3d5f-4c16-bb30-9df937ea2199#9c27ead7-8df1-4422-8566-9d197510a038\\">Tanstack Query\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</a>\uc640 \uac19\uc774 \ud754\ud55c \uc77c\uc774\ub2c8 \ud568\uc218 \ubc16 \ubcc0\uc218\ub97c \ucc38\uc870\ud560 \ub54c \uc870\uc2ec\ud558\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5b96caa2-17e3-468a-9756-2e288e37eee4\\" id=\\"5b96caa2-17e3-468a-9756-2e288e37eee4\\">DOM\uc744 \ud604\ub300\uc801\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95</h2><a href=\\"https://frontendmasters.com/blog/patterns-for-memory-efficient-dom-manipulation/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/patterns-for-memory-efficient-dom-manipulation/</a><p data-notion-block-id=\\"124866b6-cce4-4f07-8d30-dafe6436880b\\">UI\uac00 \uac04\ub2e8\ud55c \uacbd\uc6b0\uc5d0\ub294 UI \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \ubc14\ub2d0\ub77cJS\ub9cc\uc73c\ub85c \uc131\ub2a5\uc744 \uc911\uc2dc\ud55c UI\ub97c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8 \uacbd\uc6b0 <code>.innerHTML</code>\ub9cc \uc54c\uace0 \uacc4\uc2e0\ub2e4\uba74 \ubaa8\ub358 JS API\ub85c DOM \uc218\uc815 \ubc29\ubc95\uc744 \uc54c\uc544\ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"3a6644d1-aec5-404e-bbf8-87d511296f40\\" id=\\"3a6644d1-aec5-404e-bbf8-87d511296f40\\">Migration \ubc29\uc2dd \uc18c\uac1c</h2><a href=\\"https://workos.com/blog/migrating-to-next-js-app-router-with-zero-downtime\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://workos.com/blog/migrating-to-next-js-app-router-with-zero-downtime</a><a href=\\"https://medium.com/airbnb-engineering/how-airbnb-smoothly-upgrades-react-b1d772a565fd\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/airbnb-engineering/how-airbnb-smoothly-upgrades-react-b1d772a565fd</a><a href=\\"https://craft.faire.com/boosting-performance-faires-transition-to-nextjs-3967f092caaf\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://craft.faire.com/boosting-performance-faires-transition-to-nextjs-3967f092caaf</a><p data-notion-block-id=\\"a107fb85-e68f-4c42-ad5f-832230759bad\\">\uccab\ubc88\uc9f8 \uae00\uc740 NextJS \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 page router\uc5d0\uc11c app router\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uacfc\uc815, \ub450\ubc88\uc9f8 \uae00\uc740 React 16\uc744 React 18\ub85c \uc810\uc9c4\uc801 \ubc84\uc804\uc5c5 \uacfc\uc815, \uc138\ubc88\uc9f8 \uae00\uc740 React Router \uae30\ubc18 \ub80c\ub354\ub9c1 \uc11c\ubc84\ub97c NextJS\ub85c \uc810\uc9c4\uc801 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uacfc\uc815\uc744 \uc801\uc740 \uae00\uc785\ub2c8\ub2e4. \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uacfc\uc815\uc740 \uc11c\ube44\uc2a4\ub9c8\ub2e4 \ubaa8\ub450 \ub2e4\ub974\ubbc0\ub85c \uc5b4\ub5a4 \ubb38\uc81c \uc0c1\ud669\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud588\ub294\uc9c0\ub9cc \ubcf4\ub3c4\ub85d \uac00\ubccd\uac8c \uc77d\uc5b4\ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p>"}')}}]);